import{_ as s,o as n,c as p,a6 as e}from"./chunks/framework.De615z8S.js";const _=JSON.parse('{"title":"Amazon普通商品白底主图","description":"","frontmatter":{"id":"P10","title":"Amazon普通商品白底主图","chapter":"13","topic":"cross-border","status":"已公开","evidence_status":"完整模板，尚未执行图像任务或流程验证","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":["rembg","birefnet","ecommerce-image-toolkit"],"order":110},"headers":[],"relativePath":"prompts/P10.md","filePath":"prompts/P10.md"}'),t={name:"prompts/P10.md"};function l(i,a,o,c,r,m){return n(),p("div",null,[...a[0]||(a[0]=[e(`<h1 id="p10-amazon普通商品白底主图" tabindex="-1">P10 Amazon普通商品白底主图 <a class="header-anchor" href="#p10-amazon普通商品白底主图" aria-label="Permalink to &quot;P10 Amazon普通商品白底主图&quot;">​</a></h1><p>类型：生图／合成。替换项目：真实商品照片、发货清单、当前站点类目要求。下面提供完整填写示范，虚构商品DN01只作练习；正式使用时替换事实与素材。示范未附照片、未执行任务。</p><p><a href="/ai-visual-creation-handbook/ecommerce/amazon-listing">逐步教程</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请用我上传的真实商品照片制作一张Amazon US普通收纳盒白底主图。</span></span>
<span class="line"><span>以下DN01／DeskNest是虚构练习数据，不代表实际品牌或商品；正式任务必须换成已核实的商品记录。</span></span>
<span class="line"><span>练习事实：带盖桌面收纳盒；白色ABS；外尺寸长220×宽150×高120 mm；可拆隔板1个。</span></span>
<span class="line"><span>发货内容：盒体1、盖子1、隔板1。文具等场景道具不随商品发货。</span></span>
<span class="line"><span>容积、耐温、承重、防水、食品接触、认证和回收属性均未知，不补相关声明。</span></span>
<span class="line"><span>图片输入如有：图1是真实商品外观依据；图2是实际细节；图3仅参考背景和构图，不使用其商品、Logo或参数。</span></span>
<span class="line"><span>未附实拍时先给素材清单和可执行方案；不要臆画正式商品或未拍摄结构。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>画面：完整真实商品居中；纯白背景RGB(255,255,255)；没有额外文字、宣传标签、图框或场景道具。真实商品自身的标识不擅改。</span></span>
<span class="line"><span>盒体、盖子、隔板的位置与数量以实拍和发货清单为准，不复制出多件商品；整体外观、开口、边缘和色彩保持依据。</span></span>
<span class="line"><span>练习目标画布2000×2000 px、1:1，属于本次设计目标；实际导出需满足当前类目与站点要求。</span></span>
<span class="line"><span>步骤：先识别主体与配件，再抠图／蒙版，放入白底，调整大小与接触阴影，最后对照原图。</span></span>
<span class="line"><span>主体占幅参考Amazon公开指导并用实际规则复核，四边不裁掉真实结构；不以错误拉伸凑占幅。</span></span>
<span class="line"><span>如果当前工具会重绘商品，只准备白底与合成方案，后续用真实商品层完成，不生成看似相同的替代主体。</span></span>
<span class="line"><span>不要增加笔、纸夹、额外包装或未发货赠品。</span></span>
<span class="line"><span>本次范围按上述任务执行；没有图像能力时只交方案并写明状态。</span></span>
<span class="line"><span>实际执行时保留真实商品层与准确文字，逐项核对形状、颜色、盖子、隔板、配件、单位和文字。</span></span>
<span class="line"><span>目标尺寸与工具实际输出分别报告；不把画质形容词、计划路径或未创建的PSD当作已交付结果。</span></span>
<span class="line"><span>最终列：已完成、需要补的素材、无法确认的项目、实际存在的文件与下一步。</span></span></code></pre></div><p>检查：输入角色清楚、事实与未知分开、输出范围明确，实际文件与后台状态据实记录。</p>`,5)])])}const h=s(t,[["render",l]]);export{_ as __pageData,h as default};
